from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import issue_credit_note
from ledgerly.models import Invoice, LineItem
from ledgerly.errors import BillingError

def inv(status="issued", total="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(total))],status=status)

# basic
print(issue_credit_note(inv(), Decimal("10.00"), "goodwill"))
# idempotency
r1 = issue_credit_note(inv(), Decimal("10.00"), "goodwill", idempotency_key="k1")
r2 = issue_credit_note(inv(), Decimal("10.00"), "goodwill", idempotency_key="k1")
print("idem same:", r1 is r2, len(audit.events("credit_note_issued")))
# errors
for args, kw in [((inv(), Decimal("0"), "x"),{}), ((inv(), Decimal("-1"), "x"),{}),
                 ((inv("draft"), Decimal("1"), "x"),{}), ((inv(), Decimal("51"), "x"),{}),
                 ((inv(), Decimal("501"), "x"),{}), ((inv(total="1000"), Decimal("501"), "x"),{})]:
    try: issue_credit_note(*args, **kw)
    except BillingError as e: print("err", e.code)
# approval
print(issue_credit_note(inv(total="1000"), Decimal("501"), "x", approved_by="mgr"))
# float rejected
try: issue_credit_note(inv(), 10.0, "x")
except BillingError as e: print("err", e.code)
